import { readFileSync, writeFileSync } from 'node:fs';

const levels = JSON.parse(readFileSync(new URL('./levels.json', import.meta.url)));
if (levels.length !== 100) throw new Error(`expected 100 levels, got ${levels.length}`);

const O = { H: 0, V: 1 };
const lines = [];
lines.push('// GENERATED by tools/gen-levels-header.mjs from tools/levels.json — do not edit.');
lines.push('#pragma once');
lines.push('#include "../../include/domain/level.h"');
lines.push('');
lines.push(`static const TutuLevel TUTU_LEVELS[] = {`);
let prev = -1;
for (const lvl of levels) {
  if (lvl.optimalMoves < prev) throw new Error('curve not non-decreasing');
  prev = lvl.optimalMoves;
  const pieces = lvl.board
    .map((p) => `{${p.r},${p.c},${p.len},${O[p.o]}}`)
    .join(',');
  lines.push(`    {${lvl.board.length}, {${pieces}}, ${lvl.optimalMoves}},`);
}
lines.push('};');
lines.push('');
lines.push('#define TUTU_LEVEL_COUNT ((uint16_t)(sizeof(TUTU_LEVELS) / sizeof(TUTU_LEVELS[0])))');
lines.push('');

writeFileSync(new URL('../src/data/levels_data.h', import.meta.url), lines.join('\n'));
console.log(`Wrote src/data/levels_data.h (${levels.length} levels)`);
